#include "cloudiff/admin_observability.hpp"
#include <libpq-fe.h>
#include <cassert>
#include <cstdlib>
#include <iostream>
#include <string>
int main(){const char* ci=std::getenv("CLOUDIFF_POSTGRES_CONNINFO");assert(ci);cloudiff::AdminObservability api({"127.0.0.1",18260,"unit-token",ci});auto h=api.handle("GET","/health","","");assert(h.status==200);auto u=api.handle("GET","/v1/environment","","");assert(u.status==401);auto e=api.handle("GET","/v1/environment","Bearer unit-token","");assert(e.status==200&&e.body["ok"]==true&&!e.body["nodes"].empty());const auto id=e.body["nodes"][0]["node_id"].get<std::string>();PGconn* c=PQconnectdb(ci);assert(c&&PQstatus(c)==CONNECTION_OK);const char* vals[]={id.c_str()};PGresult* old=PQexecParams(c,"SELECT revision::text,state::text FROM cloudiff_v2.desired_state WHERE resource_type='node_recovery' AND resource_id=$1",1,nullptr,vals,nullptr,nullptr,0);assert(old&&PQresultStatus(old)==PGRES_TUPLES_OK);const bool had=PQntuples(old)==1;const std::string oldrev=had?PQgetvalue(old,0,0):"";const std::string oldstate=had?PQgetvalue(old,0,1):"";PQclear(old);auto p0=api.handle("GET","/v1/nodes/"+id+"/policy","Bearer unit-token","");assert(p0.status==200);auto p1=api.handle("POST","/v1/nodes/"+id+"/recovery","Bearer unit-token",R"({"automatic_reboot_enabled":false,"actor":"v34-test"})");assert(p1.status==200&&p1.body["automatic_reboot_enabled"]==false);auto p2=api.handle("GET","/v1/nodes/"+id+"/policy","Bearer unit-token","");assert(p2.status==200&&p2.body["automatic_reboot_enabled"]==false);auto bad=api.handle("POST","/v1/nodes/"+id+"/recovery","Bearer unit-token",R"({"automatic_reboot_enabled":"no","actor":"v34-test"})");assert(bad.status==422);if(had){const char* rv[]={id.c_str(),oldrev.c_str(),oldstate.c_str()};PGresult* r=PQexecParams(c,"INSERT INTO cloudiff_v2.desired_state(resource_type,resource_id,revision,state,updated_at) VALUES('node_recovery',$1,$2::bigint,$3::jsonb,now()) ON CONFLICT(resource_type,resource_id) DO UPDATE SET revision=EXCLUDED.revision,state=EXCLUDED.state,updated_at=now()",3,nullptr,rv,nullptr,nullptr,0);assert(r&&PQresultStatus(r)==PGRES_COMMAND_OK);PQclear(r);}else{PGresult* r=PQexecParams(c,"DELETE FROM cloudiff_v2.desired_state WHERE resource_type='node_recovery' AND resource_id=$1",1,nullptr,vals,nullptr,nullptr,0);assert(r&&PQresultStatus(r)==PGRES_COMMAND_OK);PQclear(r);}PGresult* a=PQexec(c,"DELETE FROM cloudiff_v2.audit_log WHERE actor='v34-test' AND action='node_recovery_policy_changed'");assert(a&&PQresultStatus(a)==PGRES_COMMAND_OK);PQclear(a);PQfinish(c);std::cout<<"admin_observability=PASS\n";return 0;}
